with flattened as (select id, created_at, coupon_codes, inline(items) from carts), enriched as (select *, round(price / sum(price) over (partition by promo), 4) as price_share, round(price / sum(price) over (partition by promo), 4) as price_share_2, max(qty) over w_grp as promo_max_qty, sum(price) over w_grp as promo_sum_price from flattened window w_grp as (partition by promo)), metrics as (select *, percent_rank() over w_recent as qty_percent_rank, dense_rank() over (partition by promo order by price_share desc nulls first) as price_share_dense_rank, count(price) over (order by cast(created_at as bigint) range between 1800 preceding and current row) as price_count_30m from enriched window w_recent as (order by qty desc nulls first)), matched_keys as (select id from metrics intersect select id from carts where customer_id in (5, 21, 29)), reconciled as (select s.* from metrics s inner join matched_keys k on s.id = k.id), metrics_carts as (select id, created_at, coupon_codes, product_id, qty, price, promo, price_share, price_share_2, promo_max_qty, promo_sum_price, qty_percent_rank, price_share_dense_rank, price_count_30m, rank() over w_hist as qty_rank, max(promo_max_qty) over (partition by promo) as promo_max_promo_max_qty, sum(price) over (partition by promo order by cast(created_at as bigint) range between 900 preceding and current row) as price_sum_15m from reconciled window w_hist as (partition by promo order by qty desc nulls last)), valid as (select created_at, product_id, qty, price, promo, price_share, price_share_2, promo_max_qty, qty_percent_rank, price_share_dense_rank, price_count_30m, promo_max_promo_max_qty, price_sum_15m, round(qty / product_id, 2) as qty_per_product_id from metrics_carts where created_at >= timestamp '2025-03-02 09:00:00' and price_count_30m is not null), enriched_carts as (select created_at, product_id, qty, price, promo, price_share, price_share_2, promo_max_qty, qty_percent_rank, price_share_dense_rank, price_count_30m, promo_max_promo_max_qty, price_sum_15m, qty_per_product_id, cume_dist() over (partition by promo order by qty_percent_rank desc) as qty_percent_rank_cume_dist, dense_rank() over (partition by promo order by price_share_dense_rank desc nulls first) as price_share_dense_rank_dense_rank, count(price_sum_15m) over (partition by promo order by cast(created_at as bigint) range between 1800 preceding and current row) as price_sum_15m_count_30m from valid) select * from (select promo, price_share_2, qty_percent_rank from enriched_carts) src unpivot (metric_value for kpi in (price_share_2 as PRICE_SHARE_2_VAL, qty_percent_rank));
